#include "stdlib/lapack/base/dgttrf.h"
#include "stdlib/math/base/special/abs.h"

/**
* Computes an LU factorization of a real tridiagonal matrix.
*
* ## Notes
*
* - The factorization is adapted from the reference LAPACK DGTTRF routine.
* - Pivot indices and singular status indices are zero-based, matching the JavaScript API. A zero at the first pivot returns zero.
* - The arrays are updated in place, in the same order as the JavaScript implementation.
*
* @param N             matrix order
* @param DL            subdiagonal elements, overwritten by multipliers
* @param strideDL      stride length for DL
* @param offsetDL      starting index for DL
* @param D             diagonal elements, overwritten by the diagonal of U
* @param strideD       stride length for D
* @param offsetD       starting index for D
* @param DU            superdiagonal elements, overwritten by the first superdiagonal of U
* @param strideDU      stride length for DU
* @param offsetDU      starting index for DU
* @param DU2           output second superdiagonal of U
* @param strideDU2     stride length for DU2
* @param offsetDU2     starting index for DU2
* @param IPIV          output zero-based pivot indices
* @param strideIPIV    stride length for IPIV
* @param offsetIPIV    starting index for IPIV
* @return              zero on success, a zero-based zero-pivot index, or -1 if N is negative
*/
LAPACK_INT API_SUFFIX(c_dgttrf_ndarray)( const LAPACK_INT N, double *DL, const LAPACK_INT strideDL, const LAPACK_INT offsetDL, double *D, const LAPACK_INT strideD, const LAPACK_INT offsetD, double *DU, const LAPACK_INT strideDU, const LAPACK_INT offsetDU, double *DU2, const LAPACK_INT strideDU2, const LAPACK_INT offsetDU2, LAPACK_INT *IPIV, const LAPACK_INT strideIPIV, const LAPACK_INT offsetIPIV ) {
	double fact;
	double temp;
	LAPACK_INT idu2;
	LAPACK_INT idu;
	LAPACK_INT idl;
	LAPACK_INT id;
	LAPACK_INT ip;
	LAPACK_INT i;
	LAPACK_INT j;

	if ( N < 0 ) {
		return -1;
	}
	if ( N == 0 ) {
		return 0;
	}
	idu2 = offsetDU2;
	ip = offsetIPIV;
	for ( i = 0; i < N; i++ ) {
		IPIV[ ip ] = i;
		if ( i < N-2 ) {
			DU2[ idu2 ] = 0.0;
		}
		if ( i < N-1 ) {
			ip += strideIPIV;
		}
		if ( i < N-3 ) {
			idu2 += strideDU2;
		}
	}
	idu2 = offsetDU2;
	ip = offsetIPIV;
	idl = offsetDL;
	id = offsetD;
	idu = offsetDU;
	for ( i = 0; i < N-2; i++ ) {
		if ( stdlib_base_abs( D[ id ] ) >= stdlib_base_abs( DL[ idl ] ) ) {
			if ( D[ id ] != 0.0 ) {
				fact = DL[ idl ] / D[ id ];
				DL[ idl ] = fact;
				D[ id+strideD ] = D[ id+strideD ] - ( fact*DU[ idu ] );
			}
		} else {
			fact = D[ id ] / DL[ idl ];
			D[ id ] = DL[ idl ];
			DL[ idl ] = fact;
			temp = DU[ idu ];
			j = id + strideD;
			DU[ idu ] = D[ j ];
			D[ j ] = temp - ( fact*D[ j ] );
			j = idu + strideDU;
			DU2[ idu2 ] = DU[ j ];
			DU[ j ] *= -fact;
			IPIV[ ip ] = i + 1;
		}
		id += strideD;
		idl += strideDL;
		idu += strideDU;
		if ( i < N-3 ) {
			idu2 += strideDU2;
		}
		ip += strideIPIV;
	}
	if ( N > 1 ) {
		i = N - 2;
		if ( stdlib_base_abs( D[ id ] ) >= stdlib_base_abs( DL[ idl ] ) ) {
			if ( D[ id ] != 0.0 ) {
				fact = DL[ idl ] / D[ id ];
				DL[ idl ] = fact;
				D[ id+strideD ] = D[ id+strideD ] - ( fact*DU[ idu ] );
			}
		} else {
			fact = D[ id ] / DL[ idl ];
			D[ id ] = DL[ idl ];
			DL[ idl ] = fact;
			temp = DU[ idu ];
			j = id + strideD;
			DU[ idu ] = D[ j ];
			D[ j ] = temp - ( fact*D[ j ] );
			IPIV[ ip ] = i + 1;
		}
	}
	id = offsetD;
	for ( i = 0; i < N; i++ ) {
		if ( D[ id ] == 0.0 ) {
			return i;
		}
		if ( i < N-1 ) {
			id += strideD;
		}
	}
	return 0;
}
